 sealed class Case {
  internal readonly string Root,Hash=H('a');internal readonly long Origin=BoundedWorker.MonotonicMilliseconds();internal Dictionary<string,object> A,L,C;internal byte[] Bundle=Encoding.UTF8.GetBytes("public inert native staging bundle"),Record;internal string Digest;
