   L=D("managerEpoch",A["managerEpoch"],"id",A["instance"],"instanceId",A["instance"],"name",A["deployment"],"originalClock",D("originMs",A["originMs"],"deadlineMs",A["deadlineMs"]),"physicalMemoryMiB",20480,"memory",D("appMiB",19456),"cpu",D("vcpus",4,"grantedUnits",400000,"appCpuPercent",400),"appId",app,"recordSha256",ProtectedAttempt.Hash(Record),"record",r,"physicalClaim",D("poolHash",H('a'),"boot",A["boot"],"actor","app-native","id",claim,"bytes",21474836480L));
   C=D("runtimeId",H('e'),"profileSha256",H('f'),"admissionSha256",H('a'),"attemptsRoot",Root,"firmwareSha256",H('a'),"initialStateSha256",H('a'),"workerSha256",H('a'));
  }
  internal byte[] Frame(){var h=NativeRpcManagerLedger.Encode(D("launch",Encoding.UTF8.GetString(NativeRpcManagerLedger.Encode(L)),"record",Encoding.UTF8.GetString(Record),"bundleBytes",Bundle.Length));var b=new byte[4+h.Length+Bundle.Length];Array.Copy(BitConverter.GetBytes(h.Length),b,4);Array.Copy(h,0,b,4,h.Length);Array.Copy(Bundle,0,b,4+h.Length,Bundle.Length);return b;}
