 public static int Main(){try{
  BoundedWorker.EnterSupervisorEnvelope(256UL*1024*1024);
  Test("actual private staging binds original launch and exact binary input",()=>{var c=new Case();using(var l=c.Open()){Check((string)l.Inspect()["state"]=="empty");c.Begin(l);var ready=(Dictionary<string,object>)c.Stage(l,c.Frame());Check((string)ready["original"]==c.Digest);Check((string)ready["bundleSha256"]==ProtectedAttempt.Hash(c.Bundle));Check(ProtectedAttempt.Hash(File.ReadAllBytes(Path.Combine(c.Root,"inputs","bundle.bin")))==ProtectedAttempt.Hash(c.Bundle));Check(File.Exists(Path.Combine(c.Root,"stage-ready.json")));Check((string)l.Inspect()["state"]=="held");}});
