  Test("truncated or changed bundle cannot publish ready",()=>{foreach(bool truncate in new[]{true,false}){var c=new Case();using(var l=c.Open()){c.Begin(l);byte[] f=c.Frame();if(truncate)Array.Resize(ref f,f.Length-1);else f[f.Length-1]^=1;Refuse(()=>c.Stage(l,f));Check(!File.Exists(Path.Combine(c.Root,"stage-ready.json")));Check(File.Exists(Path.Combine(c.Root,"inputs","bundle.bin.pending")));}}});
