  Test("inspection refuses partial record and non-directory inputs",()=>{var c=new Case();Put(Path.Combine(c.Root,"attempt.json.pending"),new byte[0]);using(var l=c.Open())Refuse(()=>l.Inspect());c=new Case();using(var l=c.Open())c.Begin(l);Put(Path.Combine(c.Root,"inputs"),new byte[]{1});using(var l=c.Open())Refuse(()=>l.Inspect());c=new Case();Directory.Delete(Path.Combine(c.Root,"transport"));Put(Path.Combine(c.Root,"transport"),new byte[]{1});using(var l=c.Open()){Refuse(()=>l.Inspect());Refuse(()=>c.Begin(l));}});
  Console.WriteLine("TOTAL "+count+" PASS; actual administrator staged files/ledger; no manager or SYSTEM task/provider execution");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
